export default {
  preset: "ts-jest/presets/default-esm",
  testEnvironment: "node",
  roots: ["<rootDir>/tests"],
  testMatch: ["**/?(*.)+(spec|test).ts"],
  testPathIgnorePatterns: [
    "<rootDir>/tests/memory/enhanced-manager.test.ts",
    "<rootDir>/tests/performance/memory-stress-testing.test.ts",
    "<rootDir>/tests/performance/memory-load-testing.test.ts",
    "<rootDir>/tests/utils/artifact-detector.test.ts",
    "<rootDir>/tests/tools/cleanup-agent-artifacts.test.ts",
  ],
  transform: {
    "^.+\\.ts$": [
      "ts-jest",
      {
        useESM: true,
        tsconfig: {
          module: "esnext",
          target: "es2020",
        },
      },
    ],
  },
  collectCoverageFrom: [
    "src/**/*.ts",
    "!src/**/*.d.ts",
    "!src/index.ts",
    // Exclude low-coverage experimental memory system files
    "!src/memory/enhanced-manager.ts",
    "!src/memory/multi-agent-sharing.ts",
    "!src/memory/pruning.ts",
    "!src/memory/visualization.ts",
    "!src/memory/integration.ts",
    "!src/memory/index.ts",
    "!src/memory/contextual-retrieval.ts",
    "!src/memory/export-import.ts",
    "!src/memory/knowledge-graph.ts",
    "!src/memory/learning.ts",
    "!src/memory/temporal-analysis.ts",
  ],
  coverageThreshold: {
    global: {
      branches: 78, // Temporarily lowered from 80% due to new user-feedback-integration.ts
      functions: 80,
      lines: 80,
      statements: 80,
    },
    // Lower threshold for complex tools
    "./src/tools/recommend-ssg.ts": {
      statements: 60,
      branches: 60,
      functions: 60,
      lines: 60,
    },
    // Lower threshold for storage layer with extensive error handling
    "./src/memory/kg-storage.ts": {
      branches: 45,
      statements: 80,
      functions: 85,
      lines: 80,
    },
    // Lower threshold for user feedback integration (new file, API-dependent)
    "./src/utils/user-feedback-integration.ts": {
      branches: 20,
      statements: 40,
      functions: 20,
      lines: 40,
    },
    // Lower branch threshold for the tree-sitter extractor (issue #112). The
    // file is dominated by grammar-edge dispatch (one branch per node-type
    // case in the Python and Go walkers, plus the lazy-load error-fallback
    // cascade for missing wasm assets / Parser.init failures). Most of those
    // branches require simulating malformed installs to exercise; statement
    // / function / line coverage stay above 80%.
    "./src/utils/ast-tree-sitter.ts": {
      branches: 60,
      statements: 80,
      functions: 80,
      lines: 80,
    },
  },
  extensionsToTreatAsEsm: [".ts"],
  moduleNameMapper: {
    "^(\\.{1,2}/.*)\\.js$": "$1",
  },
  setupFilesAfterEnv: ["<rootDir>/tests/setup.ts"],
};

